{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
)

type Entry struct {
	Name string
	Size int64
	Dir  bool
}

func dirSize(path string) int64 {
	var total int64 = 0
	_ = filepath.WalkDir(path, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.Type().IsRegular() {
			info, e := d.Info()
			if e == nil {
				total += info.Size()
			}
		}
		return nil
	})
	return total
}

func human(size int64) string {
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}
	units := []string{"KiB", "MiB", "GiB", "TiB"}
	s := float64(size)
	for i := 0; i < len(units); i++ {
		s = s / 1024.0
		if s < 1024.0 || i == len(units)-1 {
			return fmt.Sprintf("%.1f %s", s, units[i])
		}
	}
	return fmt.Sprintf("%d B", size)
}

func main() {
	entries, err := os.ReadDir(".")
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
	var list []Entry
	for _, e := range entries {
		name := e.Name()
		info, err := e.Info()
		if err != nil {
			continue
		}
		if e.IsDir() {
			sz := dirSize(name)
			list = append(list, Entry{Name: name, Size: sz, Dir: true})
		} else {
			list = append(list, Entry{Name: name, Size: info.Size(), Dir: false})
		}
	}
	sort.Slice(list, func(i, j int) bool { return list[i].Size > list[j].Size })
	for _, it := range list {
		displayName := it.Name
		if it.Dir {
			displayName = "/" + it.Name
		}
		sz := human(it.Size)
		// Right align size in width 11 to resemble original output
		fmt.Printf("%11s %s\n", sz, displayName)
	}
}
EOF

cat <<'EOF' > compile.sh
#!/bin/sh
set -e
# Build the Go program
if ! command -v go >/dev/null 2>&1; then
	echo "go toolchain required"
	exit 1
fi

go build -o executable main.go
chmod +x executable
EOF

chmod +x compile.sh

# Ignore build artifacts
cat <<'EOF' > .gitignore
/executable
EOF

# Add files to git
git add main.go compile.sh .gitignore README.md INSTALL.md LICENSE.md || true
git commit -m "Add gdu-like minimal implementation" || true

# Build and run the new executable
./compile.sh
./executable
"}

